import mongoose, { Document, Schema, Model } from "mongoose";
import bcrypt from "bcrypt";
import crypto from "crypto";

export interface IUser extends Document {
  username: string;
  password: string;
  email: string;
  tokens: number;
  adEligible: boolean;
  resetToken?: string;
  resetTokenExpiry?: Date;
  verificationToken?: string;
  verified: boolean;
  comparePassword(candidatePassword: string): Promise<boolean>;
  generateResetToken(): string;
  validateResetToken(token: string): boolean;
  generateVerificationToken(): string;
}

export interface IUserModel extends Model<IUser> {
  findByEmail(email: string): Promise<IUser | null>;
}

const userSchema = new Schema<IUser>({
  username: { type: String, required: true },
  password: { type: String, required: true },
  email: {
    type: String,
    required: true,
    unique: true,
    match: [/.+@.+\..+/, "Please enter a valid email address"],
  },
  tokens: { type: Number, default: 0 },
  adEligible: { type: Boolean, default: true },
  resetToken: { type: String }, // For password reset functionality
  resetTokenExpiry: { type: Date }, // Expiry of the reset token
  verificationToken: { type: String }, // For email verification
  verified: { type: Boolean, default: false }, // is email verified
});

// Hash the password before saving
userSchema.pre<IUser>("save", async function (next) {
  if (!this.isModified("password")) {
    return next();
  }
  const salt = await bcrypt.genSalt(10);
  this.password = await bcrypt.hash(this.password, salt);
  next();
});

// Compare password method
userSchema.methods.comparePassword = async function (candidatePassword: string): Promise<boolean> {
  return bcrypt.compare(candidatePassword, this.password);
};

// Generate a reset token and set expiry date
userSchema.methods.generateResetToken = function (): string {
  const resetToken = crypto.randomBytes(32).toString("hex");
  this.resetToken = resetToken;
  this.resetTokenExpiry = new Date(Date.now() + 3600000); // 1 hour expiry
  return resetToken;
};

// Validate reset token
userSchema.methods.validateResetToken = function (token: string): boolean {
  const isTokenValid =
    this.resetToken === token && this.resetTokenExpiry && this.resetTokenExpiry > new Date();
  return !!isTokenValid;
};

// Generate Email verification token
userSchema.methods.generateVerificationToken = function (): string {
  return crypto.randomBytes(32).toString("hex");
};

// Static method to find by email
userSchema.statics.findByEmail = function (email: string): Promise<IUser | null> {
  return this.findOne({ email: { $eq: email } });
};

export default mongoose.model<IUser, IUserModel>("User", userSchema);

import { checkAdEligibility } from "./checkAdEligibility";

const adController = {
  checkAdEligibility,
};

export default adController;

import cache from "../../cache";
import User from "../../models/User";
import { Response } from "express";
import { AuthenticatedRequest } from "../../types";

export async function checkAdEligibility(
  req: AuthenticatedRequest,
  res: Response
): Promise<void> {
  try {
    const { id } = req.user; // Extract id from authenticated user

    // Check the cache first
    let cachedData = cache.get(`adEligibility:${id}`);
    if (!cachedData) {
      // If not cached, fetch from the database
      const user = await User.findById(id);
      if (!user) {
        res.status(404).json({ error: "User not found" });
        return;
      }

      // Cache the eligibility status
      cachedData = user.adEligible;
      cache.set(`adEligibility:${id}`, cachedData);
    }

    // Respond with the cached or retrieved eligibility status
    res.status(200).json({ eligible: cachedData });
  } catch (error) {
    console.error("Error checking ad eligibility:", error);
    res.status(500).json({ error: "Failed to check ad eligibility" });
  }
}

import NodeCache from "node-cache";
import { CacheOptions } from "../types";

class CacheService {
  private cache: NodeCache;

  constructor() {
    // Initialize the cache with a TTL of 15 minutes (900 seconds)
    this.cache = new NodeCache({ 
      stdTTL: 60 * 15,
      checkperiod: 60 * 2, // Check for expired keys every 2 minutes
      useClones: false // Better performance, but be careful with object mutations
    });
  }

  // Get a value from cache
  get<T>(key: string): T | undefined {
    return this.cache.get<T>(key);
  }

  // Set a value in cache
  set<T>(key: string, value: T, ttl?: number): boolean {
    return this.cache.set(key, value, ttl || 0);
  }

  // Delete a key from cache
  del(key: string | string[]): number {
    return this.cache.del(key);
  }

  // Check if key exists
  has(key: string): boolean {
    return this.cache.has(key);
  }

  // Get cache statistics
  getStats() {
    return this.cache.getStats();
  }

  // Clear all cache
  flushAll(): void {
    this.cache.flushAll();
  }

  // Get all keys
  keys(): string[] {
    return this.cache.keys();
  }

  // Get TTL for a key
  getTtl(key: string): number | undefined {
    return this.cache.getTtl(key);
  }

  // Set TTL for existing key
  ttl(key: string, ttl: number): boolean {
    return this.cache.ttl(key, ttl);
  }

  // Utility method to get or set (cache-aside pattern)
  async getOrSet<T>(
    key: string, 
    fetchFunction: () => Promise<T>, 
    options?: CacheOptions
  ): Promise<T> {
    const cached = this.get<T>(key);

    if (cached !== undefined) {
      return cached;
    }

    const value = await fetchFunction();
    this.set(key, value, options?.ttl);

    return value;
  }

  // Memoization helper
  memoize<T extends (...args: any[]) => Promise<any>>(
    fn: T,
    keyGenerator: (...args: Parameters<T>) => string,
    ttl?: number
  ): T {
    return (async (...args: Parameters<T>) => {
      const key = keyGenerator(...args);
      const cached = this.get(key);

      if (cached !== undefined) {
        return cached;
      }

      const result = await fn(...args);
      this.set(key, result, ttl);

      return result;
    }) as T;
  }
}

const cacheService = new CacheService();

export default cacheService;

import forgotPassword from "./forgotPassword";
import login from "./login";
import logout from "./logout";
import resetPassword from "./resetPassword";
import sendVerificationEmail from "./sendVerificationEmail";
import signup from "./signup";
import { googleCallback, githubCallback, facebookCallback } from "./sso";
import verifyEmail from "./verifyEmail";

const authController = {
  login,
  signup,
  logout,
  forgotPassword,
  resetPassword,
  sendVerificationEmail,
  verifyEmail,
  googleCallback,
  githubCallback,
  facebookCallback,
