import { Request, Response } from "express";
import User from "../../models/User";
import authService from "../../services/auth";

export interface ForgotPasswordRequest extends Request {
  body: {
    email: string;
  };
}

// Forgot Password method
const forgotPassword = async (req: ForgotPasswordRequest, res: Response): Promise<Response> => {
  const { email } = req.body;

  if (!email) {
    return res.status(400).json({ error: "Email is required" });
  }

  try {
    const user = await User.findByEmail(email);
    if (!user) {
      return res.status(404).json({ error: "User not found" });
    }

    const resetToken = user.generateResetToken();
    await user.save();

    await authService.sendResetEmail(email, resetToken);

    return res.status(200).json({ message: "Password reset link sent" });
  } catch (error) {
    console.error("Forgot password error:", error);
    return res.status(500).json({ error: "Error sending reset link" });
  }
};

export default forgotPassword;

import nodemailer, { Transporter } from "nodemailer";
import { EmailOptions } from "../../types";

class AuthService {
  private transporter: Transporter;

  constructor() {
    // Configure your SMTP transporter
    this.transporter = nodemailer.createTransport({
      service: "Gmail", // or another email service provider
      auth: {
        user: process.env.EMAIL_USER, // your email address
        pass: process.env.EMAIL_PASS, // your email password or app-specific password
      },
    });
  }

  // Method to send a password reset email
  async sendResetEmail(email: string, resetToken: string): Promise<void> {
    const resetLink = `${process.env.CLIENT_URL}/reset-password?token=${resetToken}`;

    const mailOptions: EmailOptions = {
      to: email,
      subject: "Password Reset",
      html: `
        <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
          <h2>Password Reset Request</h2>
          <p>You requested a password reset for your SumItUp account.</p>
          <p>Click the button below to reset your password:</p>
          <a href="${resetLink}" style="display: inline-block; padding: 12px 24px; background-color: #007bff; color: white; text-decoration: none; border-radius: 4px; margin: 16px 0;">Reset Password</a>
          <p>Or copy and paste this link into your browser:</p>
          <p style="word-break: break-all; color: #666;">${resetLink}</p>
          <p><strong>This link will expire in 1 hour.</strong></p>
          <p>If you didn't request this password reset, please ignore this email.</p>
        </div>
      `,
    };

    try {
      await this.transporter.sendMail({
        from: process.env.EMAIL_USER,
        ...mailOptions
      });
    } catch (error) {
      console.error("Error sending reset email:", error);
      throw new Error("Error sending reset email: " + (error as Error).message);
    }
  }

  // Method to send a verification email
  async sendVerificationEmail(email: string, verificationToken: string): Promise<void> {
    const verificationLink = `${process.env.CLIENT_URL}/verify-email?token=${verificationToken}`;

    const mailOptions: EmailOptions = {
      to: email,
      subject: "Email Verification - SumItUp",
      html: `
        <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
          <h2>Welcome to SumItUp!</h2>
          <p>Thank you for signing up. Please verify your email address to complete your registration.</p>
          <p>Click the button below to verify your email:</p>
          <a href="${verificationLink}" style="display: inline-block; padding: 12px 24px; background-color: #28a745; color: white; text-decoration: none; border-radius: 4px; margin: 16px 0;">Verify Email</a>
          <p>Or copy and paste this link into your browser:</p>
          <p style="word-break: break-all; color: #666;">${verificationLink}</p>
          <p>If you didn't create an account with SumItUp, please ignore this email.</p>
        </div>
      `,
    };

    try {
      await this.transporter.sendMail({
        from: process.env.EMAIL_USER,
        ...mailOptions
      });
    } catch (error) {
      console.error("Error sending verification email:", error);
      throw new Error("Error sending verification email: " + (error as Error).message);
    }
  }

  // Method to send a generic email
  async sendEmail(options: EmailOptions): Promise<void> {
    try {
      await this.transporter.sendMail({
        from: process.env.EMAIL_USER,
        ...options
      });
    } catch (error) {
      console.error("Error sending email:", error);
      throw new Error("Error sending email: " + (error as Error).message);
    }
  }
}

const authService = new AuthService();

export default authService;

import { Request, Response } from "express";
import jwt from "jsonwebtoken";
import User from "../../models/User";

export interface LoginRequest extends Request {
  body: {
    email: string;
    password: string;
  };
}

// Login method
const login = async (req: LoginRequest, res: Response): Promise<Response> => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  try {
    console.log(`[LOGIN ATTEMPT] Email: ${email}`);
    const user = await User.findByEmail(email);
    console.log(`[LOGIN USER FOUND] ${user ? "Yes" : "No"}`);
    if (!user) {
      return res.status(401).json({ error: "User not found" });
    }

    const isMatch = await user.comparePassword(password);
    console.log(`[LOGIN PASSWORD MATCH] ${isMatch ? "Yes" : "No"}`);
    if (!isMatch) {
      return res.status(401).json({ error: "Invalid credentials" });
    }

    const jwtSecret = process.env.JWT_SECRET;
    if (!jwtSecret) {
      return res.status(500).json({ error: "JWT secret not configured" });
    }

    const token = jwt.sign({ id: user._id }, jwtSecret, {
      expiresIn: "1h",
    });

    return res.status(200).json({ token });
  } catch (error) {
    console.error("Login error:", error);
    return res.status(500).json({ error: "Error logging in" });
  }
};

export default login;

import { Request, Response } from "express";

// Logout method
const logout = (req: Request, res: Response): Response => {
  // For JWT-based auth, logout is handled client-side by removing the token
  // If using sessions, you would call req.logout() here
  return res.status(200).send({ message: "Logout successful" });
};

export default logout;

import { Request, Response } from "express";
import User from "../../models/User";

export interface ResetPasswordRequest extends Request {
  body: {
    token: string;
    newPassword: string;
  };
}

// Reset Password method
const resetPassword = async (req: ResetPasswordRequest, res: Response): Promise<Response> => {
  const { token, newPassword } = req.body;

  if (!token || !newPassword) {
    return res.status(400).json({ error: "Token and new password are required" });
  }

  try {
    // Validate password strength
    if (!/^(?=.*[a-zA-Z])(?=.*\d)[a-zA-Z\d]{8,}$/.test(newPassword)) {
      return res.status(400).json({
        error: "Password must be alphanumeric and at least 8 characters long",
      });
    }

    const user = await User.findOne({
      resetToken: { $eq: token },
      resetTokenExpiry: { $gt: new Date() },
    });

    if (!user) {
      return res.status(400).json({ error: "Invalid or expired reset token" });
    }

    user.password = newPassword;
    user.resetToken = undefined;
    user.resetTokenExpiry = undefined;
    await user.save();

    return res.status(200).json({ message: "Password reset successfully" });
  } catch (error) {
    console.error("Reset password error:", error);
    return res.status(500).json({ error: "Error resetting password" });
  }
};

export default resetPassword;

import { Request, Response } from "express";
import User from "../../models/User";
import authService from "../../services/auth";

export interface SendVerificationEmailRequest extends Request {
  body: {
    email: string;
  };
}

// Send Verification Email method
const sendVerificationEmail = async (req: SendVerificationEmailRequest, res: Response): Promise<Response> => {
  const { email } = req.body;

  if (!email) {
    return res.status(400).json({ error: "Email is required" });
  }

  try {
    const user = await User.findByEmail(email);
    if (!user) {
      return res.status(404).json({ error: "User not found" });
    }

    if (user.verified) {
      return res.status(400).json({ error: "Email is already verified" });
    }

    const verificationToken = user.generateVerificationToken();
    user.verificationToken = verificationToken;
    await user.save();

    await authService.sendVerificationEmail(email, verificationToken);

    return res.status(200).json({ message: "Verification email sent" });
  } catch (error) {
    console.error("Send verification email error:", error);
    return res.status(500).json({ error: "Error sending verification email" });
  }
};

export default sendVerificationEmail;

import { Request, Response } from "express";
import User from "../../models/User";

export interface SignupRequest extends Request {
  body: {
    username: string;
    email: string;
    password: string;
  };
}

// Signup method
const signup = async (req: SignupRequest, res: Response): Promise<Response> => {
  const { username, email, password } = req.body;

  if (!username || !email || !password) {
    return res
      .status(400)
      .json({ error: "Username, Email, and password are required" });
  }

  // Validate email
  if (!/\S+@\S+\.\S+/.test(email)) {
    return res.status(400).json({ error: "Invalid email format" });
  }

  // Validate password strength
  // Must contain at least one uppercase, one lowercase, one number, and one special character
  const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*]).{8,}$/;
  if (!passwordRegex.test(password)) {
    return res.status(400).json({
      error: "Password must be at least 8 characters long and contain at least one uppercase letter, one lowercase letter, one number, and one special character (!@#$%^&*)",
    });
  }

  try {
    const existingUser = await User.findByEmail(email);
    if (existingUser) {
      return res.status(409).json({ error: "User already exists" });
    }

    const user = new User({ username, email, password });
    await user.save();

    return res.status(201).json({ message: "User created successfully" });
  } catch (error) {
    console.error("Signup error:", error);
    return res.status(500).json({ error: "Error creating user" });
  }
};

export default signup;

import { Request, Response } from "express";
import jwt from "jsonwebtoken";
import User from "../../models/User";

export interface SSOUser {
  name: string;
  email: string;
  id?: string;
}

export interface SSORequest extends Request {
  user: SSOUser;
}

// Google Callback method
export const googleCallback = async (req: SSORequest, res: Response): Promise<Response> => {
  const user = req.user;

  if (!user || !user.email) {
    return res.status(400).json({ error: "Invalid user data from Google" });
  }

  try {
    // Check if the user already exists in the database
    let existingUser = await User.findByEmail(user.email);

    if (!existingUser) {
      // Create a new user if not found
      existingUser = new User({
        username: user.name || "Google User",
        email: user.email,
        verified: true, // OAuth users are pre-verified
      });
      await existingUser.save();
    }

    const jwtSecret = process.env.JWT_SECRET;
    if (!jwtSecret) {
      return res.status(500).json({ error: "JWT secret not configured" });
    }

    // Generate a JWT token
    const jwtToken = jwt.sign(
      { id: existingUser._id, email: existingUser.email },
      jwtSecret,
      { expiresIn: "1h" }
    );

    return res.status(200).json({ token: jwtToken });
  } catch (error) {
    console.error("Google callback error:", error);
    return res.status(500).json({ error: "Server error" });
  }
};

