import mongoose, { Document, Schema, Model } from "mongoose";

export type ContentType = 'audio' | 'image' | 'video' | 'gif' | 'url' | 'pdf' | 'book' | 'text';

export interface IContentMetadata {
  processingTime?: number; // in milliseconds
  confidence?: number; // 0-1
  wordCount?: number;
  language?: string;
  fileSize?: number; // in bytes
  originalFileName?: string;
}

export interface IContent extends Document {
  userId: mongoose.Types.ObjectId;
  title: string;
  originalContent: string;
  summary: string;
  contentType: ContentType;
  metadata: IContentMetadata;
  tags: string[];
  isFavorite: boolean;
  isPublic: boolean;
  createdAt: Date;
  updatedAt: Date;
  toggleFavorite(): Promise<IContent>;
  addTags(newTags: string[]): Promise<IContent>;
  removeTags(tagsToRemove: string[]): Promise<IContent>;
}

export interface IContentQueryOptions {
  limit?: number;
  offset?: number;
  contentType?: ContentType;
  isFavorite?: boolean;
}

export interface IContentModel extends Model<IContent> {
  findByUserId(userId: mongoose.Types.ObjectId, options?: IContentQueryOptions): Promise<IContent[]>;
  searchByTags(userId: mongoose.Types.ObjectId, tags: string[]): Promise<IContent[]>;
}

const contentSchema = new Schema<IContent>({
  userId: { 
    type: Schema.Types.ObjectId, 
    ref: 'User', 
    required: true 
  },
  title: { 
    type: String, 
    required: true 
  },
  originalContent: { 
    type: String, 
    required: true 
  },
  summary: { 
    type: String, 
    required: true 
  },
  contentType: { 
    type: String, 
    enum: ['audio', 'image', 'video', 'gif', 'url', 'pdf', 'book', 'text'],
    required: true 
  },
  metadata: {
    processingTime: { type: Number }, // in milliseconds
    confidence: { type: Number, min: 0, max: 1 },
    wordCount: { type: Number },
    language: { type: String, default: 'en' },
    fileSize: { type: Number }, // in bytes
    originalFileName: { type: String }
  },
  tags: [{ type: String }],
  isFavorite: { 
    type: Boolean, 
    default: false 
  },
  isPublic: { 
    type: Boolean, 
    default: false 
  },
  createdAt: { 
    type: Date, 
    default: Date.now 
  },
  updatedAt: { 
    type: Date, 
    default: Date.now 
  }
});

// Update the updatedAt field before saving
contentSchema.pre<IContent>('save', function(next) {
  this.updatedAt = new Date();
  next();
});

// Index for efficient queries
contentSchema.index({ userId: 1, createdAt: -1 });
contentSchema.index({ userId: 1, isFavorite: 1 });
contentSchema.index({ userId: 1, contentType: 1 });
contentSchema.index({ tags: 1 });

// Static methods
contentSchema.statics.findByUserId = function(
  userId: mongoose.Types.ObjectId, 
  options: IContentQueryOptions = {}
): Promise<IContent[]> {
  const { limit = 10, offset = 0, contentType, isFavorite } = options;

  const query: any = { userId };

  if (contentType) {
    query.contentType = contentType;
  }

  if (isFavorite !== undefined) {
    query.isFavorite = isFavorite;
  }

  return this.find(query)
    .sort({ createdAt: -1 })
    .limit(parseInt(limit.toString()))
    .skip(parseInt(offset.toString()));
};

contentSchema.statics.searchByTags = function(
  userId: mongoose.Types.ObjectId, 
  tags: string[]
): Promise<IContent[]> {
  return this.find({
    userId,
    tags: { $in: tags }
  }).sort({ createdAt: -1 });
};

// Instance methods
contentSchema.methods.toggleFavorite = function(): Promise<IContent> {
  this.isFavorite = !this.isFavorite;
  return this.save();
};

contentSchema.methods.addTags = function(newTags: string[]): Promise<IContent> {
  const uniqueTags = [...new Set([...this.tags, ...newTags])];
  this.tags = uniqueTags;
  return this.save();
};

contentSchema.methods.removeTags = function(tagsToRemove: string[]): Promise<IContent> {
  this.tags = this.tags.filter(tag => !tagsToRemove.includes(tag));
  return this.save();
};

export default mongoose.model<IContent, IContentModel>("Content", contentSchema);

import { Request, Response } from "express";
import fs from "fs";
import path from "path";
import crypto from "crypto";
import { AuthenticatedRequest, UploadedFile } from "../../types";

const UPLOAD_DIR = path.join(__dirname, "../../../uploads");
const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

interface AllowedTypes {
  [key: string]: string;
}

const ALLOWED_TYPES: AllowedTypes = {
  'image/jpeg': 'jpg',
  'image/jpg': 'jpg',
  'image/png': 'png',
  'image/gif': 'gif',
  'audio/mpeg': 'mp3',
  'audio/mp3': 'mp3',
  'audio/wav': 'wav',
  'application/pdf': 'pdf',
  'text/plain': 'txt'
};

interface UploadRequest extends AuthenticatedRequest {
  file?: UploadedFile;
}

interface FileParams extends Record<string, string> {
  fileId: string;
}

interface ListFilesRequest extends Request {
  query: {
    limit?: string;
    offset?: string;
  };
}

interface FileMetadata {
  id: string;
  originalName: string;
  filename: string;
  mimetype: string;
  size: number;
  uploadedAt: Date;
  userId: string | null;
  path: string;
}

// Ensure upload directory exists
if (!fs.existsSync(UPLOAD_DIR)) {
  fs.mkdirSync(UPLOAD_DIR, { recursive: true });
}

const fileController = {
  async uploadFile(req: UploadRequest, res: Response): Promise<Response> {
    try {
      if (!req.file) {
        return res.status(400).json({ error: "No file uploaded" });
      }

      const { originalname, mimetype, size, buffer } = req.file;

      // Validate file type
      if (!ALLOWED_TYPES[mimetype]) {
        return res.status(400).json({
          error: "File type not supported",
          supportedTypes: Object.keys(ALLOWED_TYPES)
        });
      }

      // Validate file size
      if (size > MAX_FILE_SIZE) {
        return res.status(400).json({
          error: `File too large. Maximum size is ${MAX_FILE_SIZE / (1024 * 1024)}MB`
        });
      }

      // Generate unique filename
      const fileId = crypto.randomBytes(16).toString('hex');
      const extension = ALLOWED_TYPES[mimetype];
      const filename = `${fileId}.${extension}`;
      const filepath = path.join(UPLOAD_DIR, filename);

      // Save file
      fs.writeFileSync(filepath, buffer);

      // File metadata
      const fileMetadata: FileMetadata = {
        id: fileId,
        originalName: originalname,
        filename: filename,
        mimetype: mimetype,
        size: size,
        uploadedAt: new Date(),
        userId: req.user?.id || null,
        path: filepath
      };

      return res.status(200).json({
        message: "File uploaded successfully",
        file: {
          id: fileId,
          originalName: originalname,
          filename: filename,
          size: size,
          type: mimetype,
          uploadedAt: fileMetadata.uploadedAt
        }
      });

    } catch (error) {
      console.error("Error uploading file:", error);
      return res.status(500).json({ error: "Internal Server Error" });
    }
  },

  async downloadFile(req: Request & { params: FileParams }, res: Response): Promise<Response | void> {
    try {
      const { fileId } = req.params;

      if (!fileId) {
        return res.status(400).json({ error: "File ID is required" });
      }

      // Find file (in a real app, this would be from database)
      const files = fs.readdirSync(UPLOAD_DIR);
      const matchingFile = files.find(file => file.startsWith(fileId));

      if (!matchingFile) {
        return res.status(404).json({ error: "File not found" });
      }

      const filepath = path.join(UPLOAD_DIR, matchingFile);

      // Check if file exists
      if (!fs.existsSync(filepath)) {
        return res.status(404).json({ error: "File not found on disk" });
      }

      // Get file stats
      const stats = fs.statSync(filepath);
      const extension = path.extname(matchingFile);
      const mimeType = Object.keys(ALLOWED_TYPES).find(
        key => ALLOWED_TYPES[key] === extension.substring(1)
      ) || 'application/octet-stream';

      // Set headers
      res.setHeader('Content-Type', mimeType);
      res.setHeader('Content-Length', stats.size);
      res.setHeader('Content-Disposition', `attachment; filename="${matchingFile}"`);

      // Stream file
      const fileStream = fs.createReadStream(filepath);
      fileStream.pipe(res);

    } catch (error) {
      console.error("Error downloading file:", error);
      return res.status(500).json({ error: "Internal Server Error" });
    }
  },

  async deleteFile(req: Request & { params: FileParams }, res: Response): Promise<Response> {
    try {
      const { fileId } = req.params;

      if (!fileId) {
        return res.status(400).json({ error: "File ID is required" });
      }

      // Find file
      const files = fs.readdirSync(UPLOAD_DIR);
      const matchingFile = files.find(file => file.startsWith(fileId));

      if (!matchingFile) {
        return res.status(404).json({ error: "File not found" });
      }

      const filepath = path.join(UPLOAD_DIR, matchingFile);

      // Delete file
      if (fs.existsSync(filepath)) {
        fs.unlinkSync(filepath);
      }

      return res.status(200).json({ message: "File deleted successfully" });

    } catch (error) {
      console.error("Error deleting file:", error);
      return res.status(500).json({ error: "Internal Server Error" });
    }
  },

  async listFiles(req: ListFilesRequest, res: Response): Promise<Response> {
    try {
      const { limit = "10", offset = "0" } = req.query;

      // Get all files (in a real app, this would be from database with user filtering)
      const files = fs.readdirSync(UPLOAD_DIR);

      const fileList = files
        .slice(parseInt(offset), parseInt(offset) + parseInt(limit))
        .map(filename => {
          const filepath = path.join(UPLOAD_DIR, filename);
          const stats = fs.statSync(filepath);
          const fileId = filename.split('.')[0];

          return {
            id: fileId,
            filename: filename,
            size: stats.size,
            uploadedAt: stats.birthtime,
            lastModified: stats.mtime
          };
        });

      return res.status(200).json({
        files: fileList,
        total: files.length,
        limit: parseInt(limit),
        offset: parseInt(offset)
      });

    } catch (error) {
      console.error("Error listing files:", error);
      return res.status(500).json({ error: "Internal Server Error" });
    }
  }
};

