import axios from "axios";
import * as cheerio from "cheerio";
import { assertSafePublicUrl } from "../../utils/security/safeUrl";
import { AppError } from "../../lib/errors/AppError";

const FETCH_TIMEOUT_MS = 15000;
const MAX_HTML_BYTES = 2 * 1024 * 1024;

const USER_AGENT =
  "Mozilla/5.0 (compatible; SumItUp/1.0; +https://github.com/m-a-y-a-n-k/SumItUp)";

export class UrlContentService {
  async extractMainText(rawUrl: string): Promise<string> {
    const safeUrl = await assertSafePublicUrl(rawUrl);

    const response = await axios.get(safeUrl.toString(), {
      headers: { "User-Agent": USER_AGENT },
      timeout: FETCH_TIMEOUT_MS,
      maxContentLength: MAX_HTML_BYTES,
      maxBodyLength: MAX_HTML_BYTES,
      validateStatus: (status) => status >= 200 && status < 400,
    });

    const html = response.data;
    const $ = cheerio.load(html);

    $("script, style, nav, footer, header, noscript").remove();

    let textContent = "";
    $("p").each((_i, el) => {
      textContent += `${$(el).text()} `;
    });

    if (textContent.trim().length < 50) {
      textContent = $("body").text().replace(/\s+/g, " ").trim();
    }

    if (textContent.length < 100) {
      throw new AppError(
        "The webpage provided has insufficient text content to summarize.",
        400
      );
    }

    return textContent;
  }
}

const urlContentService = new UrlContentService();

export default urlContentService;

import dns from "dns/promises";
import net from "net";
import { AppError } from "../../lib/errors/AppError";

const BLOCKED_HOSTNAMES = new Set([
  "localhost",
  "metadata.google.internal",
]);

function isPrivateIp(ip: string): boolean {
  if (net.isIPv4(ip)) {
    const parts = ip.split(".").map(Number);
    if (parts[0] === 10) return true;
    if (parts[0] === 127) return true;
    if (parts[0] === 169 && parts[1] === 254) return true;
    if (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) return true;
    if (parts[0] === 192 && parts[1] === 168) return true;
    if (parts[0] === 0) return true;
  }
  if (net.isIPv6(ip)) {
    const normalized = ip.toLowerCase();
    if (normalized === "::1" || normalized.startsWith("fe80:") || normalized.startsWith("fc") || normalized.startsWith("fd")) {
      return true;
    }
  }
  return false;
}

/**
 * Validates URL for server-side fetch (SSRF mitigation).
 * Allows only http/https to public hosts; resolves DNS and rejects private IPs.
 */
export async function assertSafePublicUrl(rawUrl: string): Promise<URL> {
  let parsed: URL;
  try {
    parsed = new URL(rawUrl);
  } catch {
    throw new AppError("Invalid URL format", 400);
  }

  if (!["http:", "https:"].includes(parsed.protocol)) {
    throw new AppError("Only HTTP and HTTPS URLs are allowed", 400);
  }

  const hostname = parsed.hostname.toLowerCase();
  if (BLOCKED_HOSTNAMES.has(hostname)) {
    throw new AppError("URL host is not allowed", 400);
  }

  if (net.isIP(hostname)) {
    if (isPrivateIp(hostname)) {
      throw new AppError("URL host is not allowed", 400);
    }
    return parsed;
  }

  const addresses = await dns.lookup(hostname, { all: true });
  for (const entry of addresses) {
    if (isPrivateIp(entry.address)) {
      throw new AppError("URL host is not allowed", 400);
    }
  }

  return parsed;
}

export default assertSafePublicUrl;

import { AuthenticatedRequest } from "@/types";
import { Response } from "express";
import fs from "fs";
import path from "path";
const pdf = require("pdf-parse");
import textUtils from "../../utils/text";

const ROOT_DIR = path.resolve(__dirname, "../../../uploads");

export async function generateBookSummary(
  req: AuthenticatedRequest,
  res: Response
): Promise<void> {
  try {
    const { bookData } = req.body;

    if (!bookData || !bookData.bookUrl) {
      res.status(400).json({ error: "Book file is required" });
      return;
    }

    const filename = bookData.bookUrl;
    const filepath = path.join(ROOT_DIR, filename);

    if (!fs.existsSync(filepath)) {
      res.status(404).json({ error: "Book file not found" });
      return;
    }

    // Check extension
    const ext = path.extname(filename).toLowerCase();
    let textContent = "";

    if (ext === ".pdf") {
      try {
        const dataBuffer = fs.readFileSync(filepath);
        const data = await pdf(dataBuffer);
        textContent = data.text;
      } catch (pdfError) {
        console.error("Book PDF parsing critical failure:", pdfError);
        res.status(500).json({ error: "Failed to parse PDF book content." });
        return;
      }
    } else if (ext === ".txt") {
      textContent = fs.readFileSync(filepath, "utf-8");
    } else {
      res.status(400).json({ error: "Unsupported book format. Please use PDF or TXT." });
      return;
    }

    // Clean text
    const cleanText = textContent.replace(/\s+/g, " ").trim();

    if (cleanText.length < 50) {
      res.status(400).json({
        error: "Book content is insufficient or unreadable (scanned?).",
        details: `Extracted ${cleanText.length} chars.`
      });
      return;
    }

    // Generate summary
    // Books are long, so we might want to be smarter, but for now reuse text summary
    // Maybe take first 50k chars to avoid memory issues (simple truncation)
    const truncatedText = textContent.slice(0, 50000);
    const summary = textUtils.generateSummaryFromText(truncatedText);

    res.status(200).json({
      summary: summary || "Unable to generate summary from book content",
    });
  } catch (error) {
    console.error("Error generating Book summary:", error);
    res.status(500).json({ error: "Internal Server Error" });
  }
}

